from taf.ul.ettf.msg_capture.expectation_builders import Event, State, Expected
from taf.ul.ettf.ta_matchers.matchers import MatchingExpectations


class WithoutDedicatedMatcher(object):
    pass


class MatchingExpectationsBuilder(object):
    def __init__(self):
        self.clear()
        self.matcher_name = ''

    def build(self):
        matching_content = {}
        for name, aggregated_matchers in self.content.items():
            matching_content[name] = []

            for multimatcher_type, matchers in aggregated_matchers.items():
                if multimatcher_type == WithoutDedicatedMatcher:
                    matching_content[name].extend([matcher() for matcher in matchers])
                else:
                    matching_content[name].append(multimatcher_type(*[matcher() for matcher in matchers]))
        self.clear()

        if not matching_content:
            return None

        expectation = MatchingExpectations(matching_content)
        expectation.set_name(self.matcher_name)
        return expectation

    def append_header(self, matcher_name, name, matcher, multimatcher_type=WithoutDedicatedMatcher):
        self.matcher_name = matcher_name
        self.append(name, matcher, multimatcher_type)

    def append(self, name, matcher, multimatcher_type=WithoutDedicatedMatcher):
        if name in self.content:
            if multimatcher_type in self.content[name]:
                self.content[name][multimatcher_type].append(matcher)
            else:
                self.content[name][multimatcher_type] = [matcher]
        else:
            self.content[name] = {}
            self.content[name][multimatcher_type] = [matcher]

    def append_unique(self, name, matcher, multimatcher_type=WithoutDedicatedMatcher):
        if name not in self.content:
            self.append(name, matcher, multimatcher_type)

    def clear(self):
        self.content = {}


class MessageDetail(Event):
    def __init__(self, name, matcher, aggregation_matcher=WithoutDedicatedMatcher):
        self.name = name
        self.matcher = self._prepare_matcher(matcher)
        self.aggregation_matcher = aggregation_matcher
        super(MessageDetail, self).__init__()


class MessageHeader(MessageDetail):
    def __init__(self, matcher_name, name, matcher, aggregation_matcher=WithoutDedicatedMatcher, policy=Expected):
        self.matcher_name = '[{}] {}'.format(policy.matcher_name_tag, matcher_name) if policy.matcher_name_tag else matcher_name
        self.policy = policy
        super(MessageHeader, self).__init__(name, matcher, aggregation_matcher)


class MessageCallback(Event):
    def __init__(self, callback):
        self.callback = callback
        super(MessageCallback, self).__init__()


class UniqueMessageDetail(MessageDetail):
    pass


class DetailedMessageBuilder(State):
    def __init__(self, *args, **kwargs):
        self.events_handlers = {
            MessageHeader: self._append_header_matcher,
            MessageDetail: self._append_matcher,
            UniqueMessageDetail: self._append_unique_matcher,
            MessageCallback: self._append_callback,
        }
        self.matcher_builder = MatchingExpectationsBuilder()
        self.callbacks = []
        self.policy = Expected
        super(DetailedMessageBuilder, self).__init__(*args, **kwargs)

    def process(self, event):
        assert type(event) in self.events_handlers, 'Not available event {}'.format(type(event))
        self.events_handlers[type(event)](event)

    def finish(self):
        matcher = self._prepare_matcher()
        if matcher.matcher is not None:
            for callback in self.callbacks:
                matcher.matcher.append_callback(callback)
            self.expectations.append(matcher)
            self._clear()

    def _clear(self):
        self.matcher_builder = MatchingExpectationsBuilder()
        self.callbacks = []
        self.policy = Expected

    def _append_header_matcher(self, event):
        self.policy = event.policy
        self.matcher_builder.append_header(event.matcher_name, event.name, lambda: event.matcher(self.storage), event.aggregation_matcher)

    def _append_matcher(self, event):
        self.matcher_builder.append(event.name, lambda: event.matcher(self.storage), event.aggregation_matcher)

    def _append_unique_matcher(self, event):
        self.matcher_builder.append_unique(event.name, lambda: event.matcher(self.storage), event.aggregation_matcher)

    def _append_callback(self, event):
        self.callbacks.append(event.callback)

    def _prepare_matcher(self):
        return self.policy().process(self.matcher_builder.build())
